#include <darkangel/rendering.hpp>
#include <algorithm>
#include <cmath>
namespace darkangel::rendering { namespace { float clamp01(float v){return std::clamp(v,0.f,1.f);} float influence(const SceneLight&l){return std::max(0.f,l.intensity)*(l.color.r*.2126f+l.color.g*.7152f+l.color.b*.0722f);} float band(float v,float t,float s){return s<=1e-5f?(v>=t?1.f:0.f):clamp01((v-t+s)/(2*s));} }
ClusterCell& ClusterAssignment::at(unsigned x,unsigned y,unsigned z){return cells[(static_cast<std::size_t>(z)*tiles_y+y)*tiles_x+x];}
const ClusterCell& ClusterAssignment::at(unsigned x,unsigned y,unsigned z)const{return cells[(static_cast<std::size_t>(z)*tiles_y+y)*tiles_x+x];}
ClusterAssignment assign_lights(const ClusterConfig&input,const ClusterView&view,std::span<const SceneLight>lights){ClusterConfig c=input;c.tile_size=std::max(1u,c.tile_size);c.depth_slices=std::max(1u,c.depth_slices);c.max_candidates=std::max(1u,c.max_candidates);c.shading_budget=std::min(c.max_candidates,std::max(1u,c.shading_budget));const unsigned w=std::max(1u,view.width),h=std::max(1u,view.height);ClusterAssignment r;r.tiles_x=(w+c.tile_size-1)/c.tile_size;r.tiles_y=(h+c.tile_size-1)/c.tile_size;r.slices=c.depth_slices;r.cells.resize(static_cast<std::size_t>(r.tiles_x)*r.tiles_y*r.slices);r.stats.clusters=r.cells.size();const float n=std::max(.0001f,view.near_plane),f=std::max(n*1.01f,view.far_plane),lr=std::log(f/n),ty=std::max(.001f,view.tan_half_fov_y),tx=ty*std::max(.01f,view.aspect);for(const auto&l:lights){if(!l.enabled)continue;if(l.type==LightType::Directional){++r.stats.directional_lights;continue;}const float range=std::max(.001f,l.range),depth=-l.position_view[2];if(depth+range<n||depth-range>f||depth<=.001f)continue;auto slice=[&](float z){return std::min(r.slices-1,static_cast<unsigned>(std::max(0.f,std::log(z/n)/lr*r.slices)));};const unsigned z0=slice(std::max(n,depth-range)),z1=slice(std::min(f,depth+range));const float minx=(l.position_view[0]-range)/(depth+range)/tx,maxx=(l.position_view[0]+range)/(depth+range)/tx,miny=(l.position_view[1]-range)/(depth+range)/ty,maxy=(l.position_view[1]+range)/(depth+range)/ty;const unsigned x0=std::min(r.tiles_x,static_cast<unsigned>(std::max(0.f,(minx*.5f+.5f)*r.tiles_x))),x1=std::min(r.tiles_x,static_cast<unsigned>(std::ceil(std::clamp(maxx*.5f+.5f,0.f,1.f)*r.tiles_x))),y0=std::min(r.tiles_y,static_cast<unsigned>(std::max(0.f,(.5f-maxy*.5f)*r.tiles_y))),y1=std::min(r.tiles_y,static_cast<unsigned>(std::ceil(std::clamp(.5f-miny*.5f,0.f,1.f)*r.tiles_y)));if(x0>=x1||y0>=y1)continue;for(unsigned z=z0;z<=z1;++z)for(unsigned y=y0;y<y1;++y)for(unsigned x=x0;x<x1;++x)r.at(x,y,z).candidates.push_back(l.id);}for(auto&cell:r.cells){if(cell.candidates.empty())continue;std::sort(cell.candidates.begin(),cell.candidates.end());cell.candidates.erase(std::unique(cell.candidates.begin(),cell.candidates.end()),cell.candidates.end());std::stable_sort(cell.candidates.begin(),cell.candidates.end(),[&](const StableId&a,const StableId&b){auto find=[&](const StableId&id){return std::find_if(lights.begin(),lights.end(),[&](const SceneLight&l){return l.id==id;});};const auto aa=find(a),bb=find(b);const float sa=aa==lights.end()?0:influence(*aa),sb=bb==lights.end()?0:influence(*bb);return sa!=sb?sa>sb:a<b;});if(cell.candidates.size()>c.max_candidates){cell.overflow=true;cell.candidates.resize(c.max_candidates);}const auto count=std::min<std::size_t>(c.shading_budget,cell.candidates.size());cell.selected.assign(cell.candidates.begin(),cell.candidates.begin()+count);++r.stats.non_empty;r.stats.candidate_links+=cell.candidates.size();r.stats.selected_links+=cell.selected.size();r.stats.overflowed+=cell.overflow?1u:0u;}return r;}
std::array<float,3> evaluate_toon(const ToonLighting&s,Color3 b,Color3 m,float intensity,float visibility,float normal,std::span<const SceneLight>local,float ao){const float response=clamp01(normal)*clamp01(visibility),v=.35f*band(response,s.band_thresholds[0],s.transition_softness)+.35f*band(response,s.band_thresholds[1],s.transition_softness)+.30f*band(response,s.band_thresholds[2],s.transition_softness);std::array<float,3>o{b.r*(s.ambient_color.r*s.ambient_strength*ao+m.r*intensity*v),b.g*(s.ambient_color.g*s.ambient_strength*ao+m.g*intensity*v),b.b*(s.ambient_color.b*s.ambient_strength*ao+m.b*intensity*v)};for(const auto&l:local){if(!l.enabled||l.type==LightType::Directional)continue;const float d=std::sqrt(l.position_view[0]*l.position_view[0]+l.position_view[1]*l.position_view[1]+l.position_view[2]*l.position_view[2]),a=std::pow(std::max(0.f,1.f-d/std::max(.001f,l.range)),std::max(.1f,l.falloff)),q=l.intensity*a*s.local_light_strength;o[0]+=b.r*l.color.r*q;o[1]+=b.g*l.color.g*q;o[2]+=b.b*l.color.b*q;}return o;}
float evaluate_fog(const FogSettings&s,float d,float h){if(!s.enabled)return 0;float a=s.exponential?1.f-std::exp(-std::max(0.f,s.density)*std::max(0.f,d)):clamp01((d-s.start)/std::max(.001f,s.end-s.start));if(s.height_falloff>0)a*=std::exp(-std::max(0.f,h-s.height)*s.height_falloff);return clamp01(a);}
Color3 apply_color_grading(const PostProcessSettings&s,Color3 l){const float e=std::exp2(s.exposure+s.exposure_compensation),g=(l.r*.2126f+l.g*.7152f+l.b*.0722f)*e;auto grade=[&](float v,float t){return std::max(0.f,((v*e-g)*s.contrast+g)*s.saturation*t);};return{grade(l.r,s.tint.r),grade(l.g,s.tint.g),grade(l.b,s.tint.b)};}
}
